probes.hyp_goal:
∀ {X : Type u} [inst : TopologicalSpace X] {Y : Type u} [inst_1 : MetricSpace Y] {f : ℕ → X → Y}
  {x : ℕ → X} (x₀ : X),
  Tendsto x atTop (𝓝 x₀) → ∀ (f₀ : X → Y), TendstoUniformly f f₀ atTop → ∀ (n : ℕ), Continuous (f n)

∀ {X : Type u} [inst : TopologicalSpace X] {Y : Type u} [inst_1 : MetricSpace Y] {f : ℕ → X → Y}
  {x : ℕ → X},
  (∀ (n : ℕ), Continuous (f n)) → ∀ (x₀ : X) (f₀ : X → Y), TendstoUniformly f f₀ atTop → Tendsto x atTop (𝓝 x₀)

∀ {X : Type u} [inst : TopologicalSpace X] {Y : Type u} [inst_1 : MetricSpace Y] {f : ℕ → X → Y}
  {x : ℕ → X},
  (∀ (n : ℕ), Continuous (f n)) → ∀ (x₀ : X), Tendsto x atTop (𝓝 x₀) → ∀ (f₀ : X → Y), TendstoUniformly f f₀ atTop
